import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor matvec_forward(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
// Warp-level reduction
__inline__ __device__ float warpReduceSum(float val) {
    for (int offset = 16; offset > 0; offset >>= 1) {
        val += __shfl_down_sync(0xffffffff, val, offset);
    }
    return val;
}
// Number of output rows handled cooperatively by a single CTA. The B vector
// (which is identical for every row) is staged into shared memory once per
// K-tile and reused across all TILE_M rows, cutting global-memory traffic
// for B by a factor of TILE_M compared to a one-row-per-block kernel.
constexpr int TILE_M = 4;
constexpr int TILE_K = 2048; // floats staged in shared memory per iteration
template <typename T>
__global__ void matvec_kernel(
    const T* __restrict__ A,
    const T* __restrict__ B,
    T* __restrict__ C,
    int M, int K)
{
    const int rowBase = blockIdx.x * TILE_M;
    const int tid = threadIdx.x;
    const int nThreads = blockDim.x;
    __shared__ float sB[TILE_K];
    float acc[TILE_M];
#pragma unroll
    for (int r = 0; r < TILE_M; r++) acc[r] = 0.0f;
    for (int kBase = 0; kBase < K; kBase += TILE_K) {
        int kTile = (K - kBase < TILE_K) ? (K - kBase) : TILE_K;
        // Cooperatively stage the current B tile into shared memory (coalesced).
        for (int i = tid; i < kTile; i += nThreads) {
            sB[i] = B[kBase + i];
        }
        __syncthreads();
        // Every thread accumulates partial dot products for all TILE_M rows
        // using the shared B tile, reading A in a coalesced pattern.
        for (int i = tid; i < kTile; i += nThreads) {
            float bVal = sB[i];
            int kIdx = kBase + i;
#pragma unroll
            for (int r = 0; r < TILE_M; r++) {
                int row = rowBase + r;
                if (row < M) {
                    acc[r] += static_cast<float>(A[(size_t)row * K + kIdx]) * bVal;
                }
            }
        }
        __syncthreads();
    }
    // Block-wide reduction per row: warp reduce then combine across warps.
    __shared__ float warpSums[TILE_M][32];
    int lane = tid & 31;
    int warpId = tid >> 5;
#pragma unroll
    for (int r = 0; r < TILE_M; r++) {
        float val = warpReduceSum(acc[r]);
        if (lane == 0) {
            warpSums[r][warpId] = val;
        }
    }
    __syncthreads();
    int numWarps = (nThreads + 31) >> 5;
    if (warpId == 0) {
#pragma unroll
        for (int r = 0; r < TILE_M; r++) {
            float val = (lane < numWarps) ? warpSums[r][lane] : 0.0f;
            val = warpReduceSum(val);
            if (lane == 0) {
                int row = rowBase + r;
                if (row < M) {
                    C[row] = static_cast<T>(val);
                }
            }
        }
    }
}
torch::Tensor matvec_forward(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
    TORCH_CHECK(A.dim() == 2, "A must be 2D (M, K)");
    TORCH_CHECK(B.dim() == 2 && B.size(1) == 1, "B must be 2D (K, 1)");
    TORCH_CHECK(A.size(1) == B.size(0), "Inner dimensions must match");
    TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
                "Expect float32 tensors");
    auto A_c = A.contiguous();
    auto B_c = B.contiguous();
    int M = (int)A_c.size(0);
    int K = (int)A_c.size(1);
    auto C = torch::empty({M, 1}, A.options());
    const float* ptrA = A_c.data_ptr<float>();
    const float* ptrB = B_c.data_ptr<float>();
    float* ptrC = C.data_ptr<float>();
    int threads = 256;
    dim3 block(threads);
    int gridBlocks = (M + TILE_M - 1) / TILE_M;
    dim3 grid(gridBlocks);
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    matvec_kernel<float><<<grid, block, 0, stream>>>(ptrA, ptrB, ptrC, M, K);
    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "matvec_kernel launch failed: ", cudaGetErrorString(err));
    return C;
}
"""

matvec_ext = load_inline(
    name="cute_matvec_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["matvec_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Matrix-vector multiplication (C = A * B) implemented with a custom
    CuTe-based CUDA kernel. Each CUDA block computes the dot product for
    one row of A with the vector B, using vectorized (float4) loads and
    a warp-shuffle + shared-memory tree reduction across the block.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = matvec_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.matvec_forward(A, B)

